<span class="line"><span style="color:#ABB2BF;">        H </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> np.</span><span style="color:#61AFEF;">tanh</span><span style="color:#ABB2BF;">(np.</span><span style="color:#61AFEF;">dot</span><span style="color:#ABB2BF;">(X, W_xh) </span><span style="color:#56B6C2;">+</span><span style="color:#ABB2BF;"> np.</span><span style="color:#61AFEF;">dot</span><span style="color:#ABB2BF;">(H, W_hh) </span><span style="color:#56B6C2;">+</span><span style="color:#ABB2BF;"> b_h)</span></span>
