<span class="line"><span style="color:#C678DD;">def</span><span style="color:#61AFEF;"> grad_clipping</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;font-style:italic;">net</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;font-style:italic;">theta</span><span style="color:#ABB2BF;">):  </span><span style="color:#7F848E;font-style:italic;">#@save</span></span>
