<span class="line"><span style="color:#ABB2BF;">            l </span><span style="color:#56B6C2;">=</span><span style="color:#61AFEF;"> loss</span><span style="color:#ABB2BF;">(y_hat, y).</span><span style="color:#61AFEF;">mean</span><span style="color:#ABB2BF;">()</span></span>
